    bimanual_or_dexterous: 'bimanual|dexterous|teleop|end-effector|gripper|anthropomorphic|biped',
    hardware_bus_or_rtos: 'ethercat|can bus|rtos|real-time|firmware|actuator|imu|odemetry|odometry',
